                if q in pts: pts.remove(q); stack.append(q); comp.append(q)
        comps.append(comp)
    container=None
    for comp in comps:
        rs=[q[0] for q in comp]; cs=[q[1] for q in comp]
        r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs); filled=set(comp)
