        ors=[q[0] for q in other]; ocs=[q[1] for q in other]
        a,b,c,d=min(ors),max(ors),min(ocs),max(ocs); h,w=b-a+1,d-c+1
        if len(other)==h*w: payload[(w,h)]=grid[a][c]
    out=[[grid[r][c] for c in range(c0,c1+1)] for r in range(r0,r1+1)]
